import { CTRL_ENTER } from '../../shared/csi-enter';
import type { WTermAdapter } from './wterm';

const isMac = typeof navigator !== 'undefined' && /Mac|iPhone|iPad/.test(navigator.platform);
const punctuation: Record<number, string> = { 186: ';:', 187: '=+', 188: ',<', 189: '-_', 190: '.>', 191: '/?', 192: '`~', 219: '[{', 220: '\\|', 221: ']}', 222: `'"` };

// In Meta mode use the layout's base virtual key, not the character generated by Option.
function optionBase(e: KeyboardEvent) {
  if (e.keyCode >= 65 && e.keyCode <= 90) return String.fromCharCode(e.keyCode + (e.shiftKey ? 0 : 32));
  if (e.keyCode >= 48 && e.keyCode <= 57) return (e.shiftKey ? ')!@#$%^&*(' : '0123456789')[e.keyCode - 48];
  return punctuation[e.keyCode]?.[Number(e.shiftKey)];
}

export function deskKeyExceptions(adapter: WTermAdapter) {
  let leftSelection = false;
  adapter.onOpen((_, signal) =>
    adapter.textarea?.addEventListener(
      'blur',
      () => {
        leftSelection = false;
      },
      { signal },
    ),
  );
  return (e: KeyboardEvent, agent: boolean): boolean => {
    if ((e.type !== 'keydown' && e.type !== 'keyup') || e.isComposing || e.keyCode === 229 || e.target !== adapter.textarea) return false;
    if (e.type === 'keydown') {
      if (leftSelection && e.key !== 'Shift') {
        leftSelection = false;
        if (e.key === 'Tab' && !e.altKey && !e.ctrlKey && !e.metaKey && !e.repeat) {
          e.stopPropagation(); // Leave forward/backward traversal to the browser, as after native Escape.
          return false;
        }
      }
      // Native Escape clears retained selections but overlooks a DOM range dragged across mounted rows.
      if (e.key === 'Escape' && !e.ctrlKey && !e.altKey && !e.metaKey && !e.shiftKey) {
        const range = document.getSelection();
        const root = adapter.native?.element;
        if (range && !range.isCollapsed && root?.contains(range.anchorNode) && root.contains(range.focusNode)) {
          adapter.native?.clearSelection();
          leftSelection = true;
          return true;
        }
      }
    }
    // Before Droid negotiates Kitty, native Ctrl+Enter is CR (submit), not queue.
    if (agent && e.type === 'keydown' && e.key === 'Enter' && e.ctrlKey && !e.altKey && !e.shiftKey && !e.metaKey && !adapter.core?.kittyKeyboardFlags()) {
      adapter.input(CTRL_ENTER);
      return true;
    }
    if (!isMac) return false;
    const ctrl = e.ctrlKey && !e.altKey && !e.metaKey && !e.shiftKey;
    // On Mac, Command+C copies; Control+C must still interrupt with selected terminal text.
    if (ctrl && e.key === 'c' && e.type === 'keydown') adapter.native?.clearSelection();
    let key: string | undefined;
    // wterm #267 reserves lowercase Ctrl+v for browser paste even on Mac. Its encoder accepts V with Control.
    if (ctrl && e.key === 'v') key = 'V';
    if (e.altKey && !e.metaKey && !e.ctrlKey && !e.getModifierState('AltGraph') && (e.key === 'Dead' || [...e.key].length === 1)) {
      if (adapter.options.macOptionIsMeta === false) {
        // Don't cancel the default: the browser supplies the layout character or composition via input.
        if (e.type === 'keydown') e.stopPropagation();
        return false;
      }
      key = optionBase(e);
    }
    if (!key || key === e.key) return false;
    // Normalize only this event's key; wterm owns negotiation, repeat, and the matching delivered release.
    const normalized = new KeyboardEvent(e.type, e);
    Object.defineProperty(normalized, 'key', { value: key });
    adapter.textarea?.dispatchEvent(normalized);
    return true;
  };
}
